def GetKey(user:str):
    key = 0
    for c in user:
        key += ord(c)
    return key

def decode(encoded:str, key:str = GetKey('user')) -> str:
    data = ''
    for letter in encoded:
        data += chr(ord(letter) - key)
    return data

def encode(data:str, key:str = GetKey('user')) -> str:
    datum = ''
    for letter in data:
        datum += chr(ord(letter) + key)        
    return datum
        
